"""Create an executed Python-only audit companion; never modify source data.

Run with nbformat available. Cells execute sequentially in one Python namespace,
not through a Jupyter kernel. Outputs are saved for inspection; no visual QA claim.
"""
from pathlib import Path
from contextlib import redirect_stdout
import io
import nbformat

root = Path(__file__).resolve().parents[1]
out = root / 'outputs/data_inventory_2026-09-28_retry'
cells = [
    nbformat.v4.new_markdown_cell('# Retry data-quality audit\n\n## tl;dr\nThe April 2026 FNS pair is structurally consistent. Most files remain unreadable within the bounded audit timeout. This is not a complete economic validation.\n\n## Context & Methods\nThe inventory was generated by scripts/inventory_audit.py with --probe-cloud and a separate output directory. Raw inputs were unchanged. Each full-file read had an eight-second timeout.\n\n### Key Assumptions\nFilenames establish candidate release/schema labels, not verified economic periods. Timeouts are access failures, not corrupt-data findings.\n\n## Data'),
    nbformat.v4.new_code_cell("from pathlib import Path\nimport json, csv\nfrom collections import Counter\nroot = Path.cwd()\nif not (root / 'scripts/inventory_audit.py').exists():\n    root = root.parents[1] if root.name == 'data_inventory_2026-09-28_retry' else root\nrecords = json.loads((root / 'outputs/data_inventory_2026-09-28_retry/file_details.json').read_text())\nprint('Access outcomes:', dict(Counter(r['read_status'] for r in records)))\nfor r in records:\n    if r['read_status'] == 'readable':\n        print('Readable:', r['path'])"),
    nbformat.v4.new_markdown_cell('## Results\n### Check the readable FNS pair\nThe following assertions independently recheck the raw CSV shape and field alignment. No monetary units or economic interpretations are inferred.'),
    nbformat.v4.new_code_cell("with (root / 'data-20260401-structure-20260401.csv').open(encoding='utf-8-sig', newline='') as f:\n    data = list(csv.reader(f))\nwith (root / 'structure-20260401.csv').open(encoding='utf-8-sig', newline='') as f:\n    schema = list(csv.DictReader(f))\nassert data[0] == [r['field name'] for r in schema]\nassert all(len(row) == len(data[0]) for row in data[1:])\nassert len({r[0] for r in data[1:]}) == len(data)-1\nprint('Rows:', len(data)-1, 'Columns:', len(data[0]))\nprint('Schema match, uniform row widths, unique region codes: passed')\nmining_pit = [r for r in schema if 'налог на доходы физических лиц' in r['russian description'].lower() and ('добыча' in r['russian description'].lower() or r['russian description'].lstrip().startswith('B '))]\nprint('Mining PIT field descriptions matched:', len(mining_pit))\nprint('Omission reason not established; do not replace unavailable mining values with zero.')"),
    nbformat.v4.new_markdown_cell('## Takeaways\nContinue with this pair for schema development, but do not claim full regional or historical validation. Finish local file downloads before reconciling sources or promoting data.\n\nExecution: code cells were run sequentially by the companion generator in a shared Python namespace, without a Jupyter kernel. Saved outputs were text-inspected; notebook-viewer visual inspection was not performed.\n\nEvidence: file_details.json, file_inventory.csv and README.md in this output directory. Tables and assertions suffice for these structural checks; no economic chart is warranted.'),
]
import os
os.chdir(root)
namespace = {}
for count, cell in enumerate((c for c in cells if c.cell_type == 'code'), 1):
    capture = io.StringIO()
    with redirect_stdout(capture):
        exec(compile(cell.source, '<audit-cell>', 'exec'), namespace)
    cell.execution_count = count
    cell.outputs = [nbformat.v4.new_output('stream', name='stdout', text=capture.getvalue())]
    print(capture.getvalue(), end='')
notebook = nbformat.v4.new_notebook(cells=cells)
nbformat.validate(notebook)
destination = out / 'audit_companion.ipynb'
nbformat.write(notebook, destination)
print(destination)
